    {"항목": "고대 편지의 관습", "내용": "고대 서신에서 재회를 사모하는 표현은 관례적이었으나 바울의 표현은 형식이 아닌 진심에서 나왔다. 실제 그는 디모데가 오기를 간절히 원했다(딤후 4:9, 21)", "목회적활용": "형식적 인사가 아닌 진심의 표현이 영적 관계를 세운다"}
