    {"영어원문": "He greatly desired to see him, that he might be filled with joy — the presence of spiritual children is the minister's great joy.", "한국어번역": "그는 그를 보기를 크게 원했다. 이는 기쁨이 가득하게 하려 함이었다 - 영적 자녀의 임재가 사역자의 큰 기쁨이다.", "핵심통찰": "영적 자녀와의 만남이 사역자의 가장 큰 기쁨이다"}
