    {"영어원문": "Unfeigned faith — faith without hypocrisy, the same within and without, in secret and in public.", "한국어번역": "거짓 없는 믿음 - 위선이 없는 믿음, 안팎이 동일하며 비밀 중에도 공중 앞에서도 동일한 믿음.", "핵심통찰": "참된 믿음은 숨은 데서도 드러난 데서도 동일하다"}
