    {"교리": "두려움을 이기는 믿음", "설명": "성경은 반복해서 '두려워 말라'고 말씀한다. 신자의 두려움은 믿음으로 이긴다", "관련구절": "사 41:10, 요일 4:18, 히 13:6, 롬 8:15"}
