    {"대지": "1대지: 능력의 영 (담대함)", "내용": "성령은 능력(뒤나미스)의 영이다. 이는 인간적 힘이 아닌 하나님의 초자연적 능력이다. 이 능력이 사역의 동력이다", "예화_적용": "베드로가 오순절 이후 완전히 달라진 것은 성령의 능력 때문이었다"},
    {"대지": "2대지: 사랑의 영 (동기)", "내용": "능력에 사랑이 동반된다. 사랑 없는 능력은 폭력이다. 사역의 동기는 사랑이어야 한다", "예화_적용": "의사의 칼은 사람을 살리지만 강도의 칼은 사람을 죽인다. 차이는 동기이다"},
    {"대지": "3대지: 근신의 영 (균형)", "내용": "근신(소프로니스모스)은 자제되고 건전한 판단이다. 능력과 사랑이 근신으로 균형잡힌다", "예화_적용": "열정적인 운전사도 브레이크가 없으면 위험하다. 근신이 영적 브레이크이다"},
    {"대지": "결론", "내용": "두려움의 영을 버리고 하나님이 주신 능력과 사랑과 근신의 영을 취하자. 이것이 사역자의 무장이다", "예화_적용": "본래 주신 무장을 벗어 던지고 전장에 나가는 군인은 없다"}
