    {"구절": "사 41:10", "연결점": "두려워 말라 내가 너와 함께 함이니라 - 두려워 말라", "구분": "구약"},
    {"구절": "신 31:6", "연결점": "마음을 강하게 하고 담대히 하라 - 두려움을 물리치는 격려", "구분": "구약"},
    {"구절": "수 1:9", "연결점": "강하고 담대하라 두려워 말며 놀라지 말라 - 담대함의 명령", "구분": "구약"}
