    {"원어": "πρόθεσιν (프로데신)", "의미_문법": "뜻 - 명사 여성 단수 대격. 미리 정하신 계획, 목적", "설교포인트": "구원은 하나님의 영원한 작정이다. 우연이 아닌 계획된 목적의 실현이다"},
    {"원어": "πρὸ χρόνων αἰωνίων (프로 크로논 아이오니온)", "의미_문법": "영원한 때 전부터 - 전치사 + 명사 복수 속격. 시간 이전의 영원", "설교포인트": "은혜는 창세 전부터 주어졌다. 시간의 창조 이전부터 우리를 향한 하나님의 계획이 있었다"}
