    {"항목": "영지주의의 시작", "내용": "1세기 말 영지주의가 태동하며 숨은 지식으로 구원받는다는 거짓 교리가 퍼지기 시작했다. 바울은 그리스도 안의 은혜로 주어진 영원 전의 선택을 강조한다", "목회적활용": "거짓 교리는 숨은 지식이나 특별한 행위를 요구하지만 참 복음은 은혜의 선물을 선포한다"}
