    {"대지": "1대지: 구주의 나타나심 (성육신)", "내용": "영원 전의 계획이 그리스도의 나타나심으로 실현되었다. 하늘의 왕이 우리 가운데 오셨다", "예화_적용": "왕이 왕궁에 머물지 않고 백성 가운데 내려오심 같은 은혜"},
    {"대지": "2대지: 사망의 폐지 (승리)", "내용": "그리스도는 사망을 폐하셨다. 사망의 권세가 무너졌다. 신자에게 사망은 더 이상 끝이 아니다", "예화_적용": "사형 선고가 취소된 죄수의 기쁨 같은 구원의 감격"},
    {"대지": "3대지: 생명의 계시 (복음)", "내용": "복음은 감춰진 생명과 불멸을 드러낸다. 영생이 더 이상 모호한 소망이 아니다", "예화_적용": "어두운 동굴에 램프를 켜는 것처럼 복음이 영원의 실재를 비춘다"},
    {"대지": "결론", "내용": "사망을 폐하시고 생명을 드러내신 그리스도를 찬양하자. 이 복음이 우리의 영원한 소망이다", "예화_적용": "죽음의 계곡을 지나도 두려워 않는 것은 그리스도께서 사망을 폐하셨기 때문이다"}
