    {"새찬송가": "165", "통일찬송가": "155", "제목": "주님께 영광", "선정이유": "승리의 주님을 찬양한다"},
    {"새찬송가": "160", "통일찬송가": "149", "제목": "무덤에 머물러", "선정이유": "사망을 깨뜨리고 부활하신 주를 찬양한다"},
    {"새찬송가": "488", "통일찬송가": "539", "제목": "이 몸의 소망 무엔가", "선정이유": "생명과 썩지 않는 것에 대한 소망을 고백한다"}
