    {"상황": "영원에 대한 불확실함에 시달리는 성도", "성경원리": "복음은 생명과 썩지 않을 것을 명확히 드러낸다. 영원은 모호한 철학이 아닌 그리스도 안의 확실한 실재이다", "실제적용": "부활하신 그리스도를 묵상하게 하고 그분의 약속을 성경 말씀으로 붙들도록 인도하라"}
