    {"교리": "사역자의 외로움", "설명": "그리스도의 참된 종은 때로 극심한 외로움을 경험한다. 이것도 십자가의 한 모습이다", "관련구절": "시 22:1, 사 63:3, 막 15:34, 딤후 4:10"}
