    {"영어원문": "Ministers must not think strange when friends forsake them in trouble.", "한국어번역": "사역자는 친구들이 환난 중에 자신을 버릴 때 이상히 여기지 말아야 한다.", "핵심통찰": "환난 중의 배신은 사역의 일부로 받아들여야 한다"}
